      || !Array.isArray(receipt.labels) || !receipt.labels.includes('SENT')
      || !Array.isArray(receipt.to)
      || !receipt.to.some(a => typeof a === 'string' && a.trim().toLowerCase() === spec.recipient)
      || receipt.subject !== spec.subject) return false;
