    (!b.max_age_days||timing.publicationMaxAgeMs<=b.max_age_days*86400000));
  const observedOpen=d.lead_kind==='paid_request'&&d.source_status==='open'&&
    Boolean(d.checked_at&&d.checked_at.slice(0,10)===today);
