    if(currentUndatedRequest)notes.push(relativeAgeFits?
      'The original publication label “'+timing.publicationLabel+'” was checked today. Its conservative age window satisfies the customer brief; no calendar date is inferred.':
      futureDeadline?'Issue date is unavailable; open status and a future closing date were checked today.':
      'Issue date is unavailable; the open source was checked today and displayed “'+timing.closingLabel+'”. Recheck when that observed interval elapses.');
    else reasons.push(b.max_age_days?
      'Record the original request date or a current original publication label whose full age window fits the customer limit.':
      'Record the original request date, or recheck an open paid request with a supported publication or positive remaining-time label today.');
  }
  if(!d.deadline_at&&!d.deadline_on&&timing?.closingElapsed)
    reasons.push('The displayed closing interval has elapsed; recheck the original source before preparing this lead.');
  if(!d.checked_at)reasons.push('Record when the source was checked.');
  if(!d.demand)reasons.push(d.lead_kind==='company_fit'?'Describe the observed business need or workflow.':'Describe the buyer request.');
  if(b.lead_kind!=='any'&&d.lead_kind!==b.lead_kind)reasons.push('This buyer signal does not match the lead type in the customer brief.');
  if(!d.fit)reasons.push('Explain the match to this customer.');
