function leadReplacementOptions(ledger,{editionId,asOf=new Date().toISOString()}={}){
  const root=validateRoot(ledger),base=find(root.editions,id(editionId,'original edition ID'),'customer edition');
  const at=instant(asOf,'reserve review time',true),pack=find(root.packs,base.pack_id,'customer brief');
  const active=!withdrawn(root,base.id)&&!root.editions.some(row=>row.replaces===base.id);
  const customer=customerKeys(pack.document.customer);
  const used=new Set(root.editions.filter(row=>!withdrawn(root,row.id)&&intersects(customerKeys(row.brief.customer),customer))
    .flatMap(row=>row.leads.flatMap(lead=>keys(lead.document))));
  const reserves=root.leads.filter(row=>row.pack_id===base.pack_id).map(row=>{
    const checked=quality(row,{...pack,document:base.brief},at),reasons=[...checked.reasons];
    if(keys(row.document).some(value=>used.has(value)))reasons.push('This customer already has this company or request in a prepared edition.');
    if(base.kind==='sample')reasons.push('Prepare replacements from an original paid pack or its current replacement.');
    if(!active)reasons.push('Choose the current, unwithdrawn edition.');
