function createLeadFulfillmentReadSnapshot(ledger){
  need(plain(ledger),'Open the original sales workspace.');
  if(readSnapshots.has(ledger.lead_fulfillment))return {...ledger};
  const root=validateRoot(ledger.lead_fulfillment===undefined?{}:
    {lead_fulfillment:clone(ledger.lead_fulfillment)});
  const identity=hash(root),pending=[root];
  while(pending.length){
    const value=pending.pop();
